import bisect
import hashlib


class HashRing:
    def __init__(self, nodes=(), replicas=100):
        self._replicas = replicas
        self._nodes = set()
        self._owner = {}                  # position on the ring -> node
        self._positions = []              # the positions, sorted
        for node in nodes:
            self.add(node)

    @staticmethod
    def _hash(text):
        return int(hashlib.md5(text.encode("utf-8")).hexdigest(), 16)

    def add(self, node):
        if node in self._nodes:
            return
        self._nodes.add(node)
        for replica in range(self._replicas):
            self._owner[self._hash(f"{node}#{replica}")] = node
        self._positions = sorted(self._owner)

    def remove(self, node):
        if node not in self._nodes:
            return
        self._nodes.discard(node)
        self._owner = {position: owner for position, owner in self._owner.items() if owner != node}
        self._positions = sorted(self._owner)

    def node_for(self, key):
        if not self._positions:
            return None
        index = bisect.bisect(self._positions, self._hash(key)) % len(self._positions)   # first position after the key, wrapping
        return self._owner[self._positions[index]]
